<div class="d-flex justify-content-between align-items-center mb-3"><div><h1 class="h3">Opening Stock</h1><p class="text-secondary mb-0">Create the initial cylinder inventory as a real stock batch.</p></div></div>
<div class="card shadow-sm mb-3"><div class="card-body"><form id="form"><div class="row g-3"><div class="col-md-3"><label class="form-label">Batch date</label><input name="batch_date" type="date" class="form-control" required></div><div class="col-md-3"><label class="form-label">Cylinder group ID</label><input name="group_id" type="number" class="form-control" required></div><div class="col-md-2"><label class="form-label">Quantity</label><input name="quantity" type="number" min="1" class="form-control" value="1" required></div><div class="col-md-2"><label class="form-label">Actual gas kg</label><input name="actual_gas" class="form-control" inputmode="decimal" value="0" required></div><div class="col-md-2"><label class="form-label">Condition</label><select name="condition_code" class="form-select"><option>GOOD</option><option>DAMAGED</option></select></div><div class="col-md-3"><label class="form-label">Location</label><select name="location" id="location" class="form-select"><option value="SHOP">SHOP</option><option value="ISSUED">ISSUED</option></select></div><div class="col-md-3" id="customerWrap"><label class="form-label">Customer ID</label><input name="customer_id" class="form-control" type="number"></div><div class="col-md-3"><label class="form-label">Code mode</label><select name="code_mode" class="form-select"><option>AUTO</option><option>MANUAL</option></select></div><div class="col-md-3"><label class="form-label">Manual codes</label><input name="codes" class="form-control" placeholder="One per cylinder"></div><div class="col-12"><button class="btn btn-primary">Post Opening Stock</button></div></div></form></div></div>
<div class="card shadow-sm"><div class="card-body"><h5>Opening Stock History</h5><div class="table-responsive"><table class="table"><thead><tr><th>ID</th><th>Date</th><th>Source</th><th>Cylinders</th><th>Status</th><th>Created by</th><th>Action</th></tr></thead><tbody id="rows"></tbody></table></div></div></div>
<script>$(function(){const today=new Date().toISOString().slice(0,10);$('input[name=batch_date]').val(today);$('#customerWrap').hide();$('#location').on('change',function(){if(this.value==='ISSUED')$('#customerWrap').show();else $('#customerWrap').hide();});function load(){$.getJSON('<?=e(url('/opening-stock/data'))?>',function(r){let b=$('#rows').empty();r.data.rows.forEach(x=>b.append('<tr><td>'+x.id+'</td><td>'+x.batch_date+'</td><td>'+x.source+'</td><td>'+x.cylinder_count+'</td><td>'+x.status+'</td><td>'+ $('<span>').text(x.created_by_name||'').html()+'</td><td>'+ (x.status==='POSTED' ? '<button class="btn btn-sm btn-outline-danger void-batch" data-id="'+x.id+'">Void</button>' : '<span class="text-muted">Voided</span>') +'</td></tr>'));});}$('#form').on('submit',function(e){e.preventDefault();$.post('<?=e(url('/opening-stock'))?>',$(this).serialize()).done(function(r){if(r.ok){alert(r.message);$('#form')[0].reset();$('input[name=batch_date]').val(today);load();}else alert(r.message);}).fail(function(x){alert(x.responseJSON?.message||'Save failed');});});load();});</script>